import * as THREE from 'three/webgpu';
import {
  meshStandardNodeMaterial,
  uniform,
  color,
  float,
  mul,
  div,
  sub,
  neg,
  viewPosition,
  mix,
  sin,
  time,
  add,
  length,
  max,
  min
} from 'three/tsl';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';
import { createMSDFText } from '@/text';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.position.set(0, 0, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);
  group.userData.handlers = {};

  // ---------- Geometry ----------
  const pointRadius = 0.012;
  const icoGeometry = new THREE.IcosahedronGeometry(pointRadius, 0);

  // ---------- Core Particles ----------
  const coreCount = 90;
  const coreGeometry = icoGeometry.clone();
  const coreMaterial = meshStandardNodeMaterial({
    color: color('#ff2a38'),
    emissive: color('#ff2a38'),
    emissiveIntensity: uniform('coreEmissiveIntensity', 1.5),
    transparent: true,
    opacity: float(1.0),
    depthWrite: false,
    blending: THREE.AdditiveBlending
  });
  const coreMesh = new THREE.InstancedMesh(coreGeometry, coreMaterial, coreCount);
  coreMesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
  coreMesh.instanceColor = null;
  group.add(coreMesh);

  // Core instance data
  const coreInfo = [];
  for (let i = 0; i < coreCount; i++) {
    const pos = new THREE.Vector3(
      (Math.random() - 0.5) * 1.0,
      (Math.random() - 0.5) * 1.0,
      (Math.random() - 0.5) * 1.0
    );
    const matrix = new THREE.Matrix4().makeTranslation(pos.x, pos.y, pos.z);
    coreMesh.setMatrixAt(i, matrix);
    coreInfo.push({ anchor: pos.clone(), distance: pos.length() });
  }

  // ---------- Field Particles ----------
  const fieldCount = 1200 - coreCount;
  const fieldGeometry = icoGeometry.clone();
  const opacityNode = mix(
    float(0.9),
    float(0.15),
    div(neg(viewPosition.z), float(5.0))
  );
  const fieldMaterial = meshStandardNodeMaterial({
    color: color('#e8ecf2'),
    metalness: float(0.0),
    roughness: float(1.0),
    emissiveIntensity: float(0.0),
    transparent: true,
    opacity: opacityNode,
    depthWrite: false,
    blending: THREE.NormalBlending
  });
  const fieldMesh = new THREE.InstancedMesh(fieldGeometry, fieldMaterial, fieldCount);
  fieldMesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
  fieldMesh.instanceColor = null;
  group.add(fieldMesh);

  // Field instance data
  const fieldInfo = [];
  const ellipsoid = { x: 6, y: 4, z: 5 };
  const centerZ = -1.5;
  for (let i = 0; i < fieldCount; i++) {
    const u = Math.random();
    const v = Math.random();
    const theta = u * 2.0 * Math.PI;
    const phi = Math.acos(2.0 * v - 1.0);
    const r = Math.cbrt(Math.random()); // uniform inside sphere
    const x = r * ellipsoid.x * Math.sin(phi) * Math.cos(theta);
    const y = r * ellipsoid.y * Math.sin(phi) * Math.sin(theta);
    const z = r * ellipsoid.z * Math.cos(phi) + centerZ;
    const pos = new THREE.Vector3(x, y, z);
    const matrix = new THREE.Matrix4().makeTranslation(pos.x, pos.y, pos.z);
    fieldMesh.setMatrixAt(i, matrix);
    fieldInfo.push({ anchor: pos.clone(), distance: pos.distanceTo(new THREE.Vector3(0, 0, 0)) });
  }

  // ---------- Text ----------
  const textGroup = new THREE.Group();

  const heroText = createMSDFText('NOVA ATELIER', {
    fontFamily: 'Lora',
    fontSize: 124,
    fontWeight: 600,
    color: '#ff2a38',
    letterSpacing: -0.01,
    lineHeight: 1.02,
    anchor: new THREE.Vector3(0, 0.5, 0.5)
  }, ctx.fontAtlas);
  heroText.position.set(0, 0.5, 0.5);
  textGroup.add(heroText);

  const subheadText = createMSDFText('Precision instruments for the dark hours.', {
    fontFamily: 'JetBrains Mono',
    fontSize: 40,
    fontWeight: 400,
    color: '#e8ecf2',
    letterSpacing: 0.02,
    lineHeight: 1.35,
    anchor: new THREE.Vector3(0, -0.25, 0.5)
  }, ctx.fontAtlas);
  subheadText.position.set(0, -0.25, 0.5);
  textGroup.add(subheadText);

  const captionText = createMSDFText('EST. 2019 / GENEVA AND KYOTO', {
    fontFamily: 'JetBrains Mono',
    fontSize: 18,
    fontWeight: 400,
    color: '#e8ecf2',
    letterSpacing: 0.08,
    lineHeight: 1.4,
    anchor: new THREE.Vector3(0, -2.25, 0.5)
  }, ctx.fontAtlas);
  captionText.position.set(0, -2.25, 0.5);
  textGroup.add(captionText);

  group.add(textGroup);

  // ---------- Animation ----------
  const timelines = [];

  // Core pulse (emissive intensity sine)
  const coreEmissiveUniform = coreMaterial.uniforms.coreEmissiveIntensity;
  const pulseUpdate = (delta) => {
    const t = performance.now() * 0.001;
    coreEmissiveUniform.value = 1.5 + 0.3 * Math.sin(2 * Math.PI * 0.1 * t);
  };

  // Ambient drift
  const driftUpdate = (delta) => {
    const timeSec = performance.now() * 0.001;
    const freq = 0.05; // Hz
    const amp = 0.04;
    // Core particles
    for (let i = 0; i < coreCount; i++) {
      const info = coreInfo[i];
      const angle = 2 * Math.PI * freq * timeSec + i;
      const offset = new THREE.Vector3(
        Math.cos(angle) * amp,
        Math.sin(angle) * amp,
        0
      );
      const pos = info.anchor.clone().add(offset);
      const mat = new THREE.Matrix4().makeTranslation(pos.x, pos.y, pos.z);
      coreMesh.setMatrixAt(i, mat);
    }
    coreMesh.instanceMatrix.needsUpdate = true;

    // Field particles
    for (let i = 0; i < fieldCount; i++) {
      const info = fieldInfo[i];
      const angle = 2 * Math.PI * freq * timeSec + i;
      const offset = new THREE.Vector3(
        Math.cos(angle) * amp,
        Math.sin(angle) * amp,
        0
      );
      const pos = info.anchor.clone().add(offset);
      const mat = new THREE.Matrix4().makeTranslation(pos.x, pos.y, pos.z);
      fieldMesh.setMatrixAt(i, mat);
    }
    fieldMesh.instanceMatrix.needsUpdate = true;
  };

  // Register update loop
  group.userData.update = (delta) => {
    pulseUpdate(delta);
    driftUpdate(delta);
  };

  // Apply cinematic primitives from config
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (typeof fn === 'function') {
        fn(group, prim.params);
      }
    }
  }

  // Cleanup
  group.userData.cleanup = () => {
    // Dispose geometries and materials
    coreGeometry.dispose();
    fieldGeometry.dispose();
    coreMaterial.dispose();
    fieldMaterial.dispose();
    // Dispose text meshes if they have geometry/material
    textGroup.traverse((obj) => {
      if (obj.isMesh) {
        obj.geometry?.dispose();
        obj.material?.dispose();
      }
    });
    // Kill GSAP timelines
    timelines.forEach((tl) => tl.kill());
    // Remove update reference
    delete group.userData.update;
  };

  return group;
}
